pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 extraAmount, address depositor) public {
        vm.assume(depositor != address(0));
        vm.assume(depositAmount > 0);
        vm.assume(depositAmount < type(uint128).max / 2);
        vm.assume(extraAmount < type(uint128).max / 2);

        // Fund depositor
        vm.deal(depositor, depositAmount + extraAmount);

        // Deposit
        vm.startPrank(depositor);
        c.deposit{value: depositAmount}();
        vm.stopPrank();

        // Record balance before withdraw
        uint256 balanceBefore = address(c).balance;
        uint256 creditBefore = c.credit(depositor);

        // Withdraw
        vm.startPrank(depositor);
        c.withdrawAll();
        vm.stopPrank();

        uint256 balanceAfter = address(c).balance;
        uint256 creditAfter = c.credit(depositor);

        // Assert: balance must decrease exactly by the positive credit that existed before withdraw.
        // If creditBefore > 0, then balance should have dropped by creditBefore.
        // If creditBefore == 0, no decrease (difference 0).
        assertTrue(balanceBefore - balanceAfter == creditBefore);
    }
}

