pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Restrict amounts to admissible positive domain and ensure withdraw <= deposit to avoid revert due to insufficient balance
        vm.assume(depositAmount > 0 && depositAmount < type(uint72).max);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);

        address caller = makeAddr("caller");
        vm.deal(caller, depositAmount);

        // Deposit
        vm.prank(caller);
        c.deposit{value: depositAmount}();

        // To ensure a successful withdrawAll, caller's credit must equal depositAmount; withdrawAll always withdraws the full credit.
        // Since we want a successful withdrawal, we ensure credit[caller] == depositAmount, and oCredit > 0.
        // In the general property we care about the state after a successful withdrawAll.
        // We only call withdrawAll when credit > 0. We can directly call withdrawAll; if oCredit == 0, it does nothing and credit remains depositAmount, but that's not a bug-trigger scenario.
        // We restrict to cases where credit > 0 (already satisfied by depositAmount > 0).
        uint256 creditBefore = c.credit(caller);

        // Attempt withdrawAll; it may revert if the call to caller fails, but caller is an EOA so low-level call always succeeds.
        vm.prank(caller);
        try c.withdrawAll() { } catch { }

        uint256 creditAfter = c.credit(caller);

        // General invariant: After withdrawAll completes (regardless of whether it did a withdrawal or not?)
        // The reference implementation sets credit to 0 if oCredit > 0; otherwise leaves unchanged.
        // Actually, if oCredit == 0, creditBefore remains depositAmount, and creditAfter also depositAmount, so creditAfter == creditBefore (non-zero). This is allowed.
        // The property must be universally true for reference and false for the mutant in some case.
        // Since withdrawAll in reference always sets credit to 0 when oCredit > 0, we can state: if creditBefore > 0, then creditAfter == 0.
        // This is true for reference, false for mutant (sets to 1).
        if (creditBefore > 0) {
            assertTrue(creditAfter == 0);
        } else {
            assertTrue(creditAfter == creditBefore); // redundant, just ensures no revert false positive
        }
    }
}

