pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 attackDepth) public {
        // Restrict deposit to a practical range; attackDepth caps recursive calls.
        depositAmount = bound(depositAmount, 1e15, 100 ether);
        attackDepth = bound(attackDepth, 1, 10);

        // Deploy the reentrant attacker.
        Attacker attacker = new Attacker(c, attackDepth);

        // Fund the attacker (EOA part) and make a deposit into C.
        vm.deal(address(this), depositAmount);
        c.deposit{value: depositAmount}();
        // Allocate credit to the attacker's contract.
        // Direct transfer via deposit is easier: attacker makes deposit.
        vm.deal(address(attacker), depositAmount);
        vm.prank(address(attacker));
        c.deposit{value: depositAmount}();

        // Record balance before attack.
        uint256 balanceBefore = address(c).balance;

        // Attack: the attacker initiates withdrawAll.
        vm.prank(address(attacker));
        attacker.attack();

        // After the attack, the invariant: contract's ether balance >= total credit.
        // Sum of all credits is just the attacker's credit here (no other depositors).
        uint256 totalCredit = c.credit(address(attacker));
        assertTrue(address(c).balance >= totalCredit);
    }
}

contract Attacker {
    C public target;
    uint256 public depth;
    uint256 public count;

    constructor(C _target, uint256 _depth) {
        target = _target;
        depth = _depth;
    }

    function attack() external {
        target.withdrawAll();
    }

    receive() external payable {
        if (count < depth) {
            count++;
            target.withdrawAll();
        }
    }
}

