pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 attackerSeed, address other) public {
        // Keep deposit in a wide admissible range, skip zero to avoid trivial passes
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        uint256 initialDeposit = bound(depositAmount, 1, type(uint128).max);
        vm.assume(other != address(this) && other != address(0) && other != address(c));
        vm.assume(other != address(this) && other != address(0) && other != address(c));

        // Derive a deterministic attacker address from seed, avoiding collisions
        address attacker = address(uint160(uint256(keccak256(abi.encode(attackerSeed)))));
        vm.assume(attacker != other && attacker != address(this) && attacker != address(0) && attacker != address(c));

        // Fund the attacker and a harmless depositor
        vm.deal(attacker, 0);
        vm.deal(other, 0);

        // Deploy a re-entrant attacker that calls c.withdrawAll() twice
        ReentrantAttacker reentranter = new ReentrantAttacker();
        // We need the attacker's address to be the beneficiary inside the helper.  
        // Instead of fuzzing the raw attacker address, we use a minimal helper that embodies the re-entrant call
        // and that helper itself is the adversarial party.
        // The helper receives Ether on behalf of the attacker and forwards it.
        address adversarial = address(reentranter);
        vm.assume(adversarial != other && adversarial != address(this) && adversarial != address(0) && adversarial != address(c));

        // 1. Deposit by other to have initial non-zero credit (the bug requires sufficient balance)
        vm.prank(other);
        c.deposit{value: initialDeposit}();

        // 2. Deposit by the adversarial helper so that it has credit
        vm.prank(adversarial);
        c.deposit{value: initialDeposit}();

        uint256 balanceBefore = address(c).balance;

        // 3. Trigger withdrawAll through the adversarial helper; it will attempt re-entrancy
        vm.prank(adversarial);
        reentranter.attack(address(c));

        uint256 balanceAfter = address(c).balance;
        uint256 creditOther = c.credit(other);
        uint256 creditAdversarial = c.credit(adversarial);

        // After the sequence, the invariant for the correct contract is:
        // ether balance of the contract >= sum of all outstanding credits
        // The bug breaks this: the re-entrant attack drains more ether than the attacker's recorded credit,
        // causing balance to drop below total credits.  
        // We assert this general rule holds for reference and fails for the buggy version.
        assertTrue(balanceAfter >= creditOther + creditAdversarial);
    }
}

// Minimal adversarial helper that re-enters withdrawAll when receiving Ether
contract ReentrantAttacker {
    bool private attacking;

    function attack(address target) external payable {
        attacking = true;
        C(target).withdrawAll();
        attacking = false;
        // send any leftover Ether back to msg.sender (the pranked attacker)
        payable(msg.sender).transfer(address(this).balance);
    }

    receive() external payable {
        if (attacking) {
            C(msg.sender).withdrawAll();
        }
    }
}

