pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 attackerDeposit) public {
        // Admissible domain: non-zero amount, attacker deposit bounded to avoid overflow
        vm.assume(amount > 0);
        vm.assume(attackerDeposit >= amount);
        vm.assume(attackerDeposit <= type(uint256).max - amount);

        // Deploy reentrant attacker that calls withdrawAll again
        Attacker attacker = new Attacker(c);
        address attackerAddr = address(attacker);

        // Fund the honest user with a deposit
        address honest = address(0x1234);
        vm.deal(honest, amount);
        vm.prank(honest);
        c.deposit{value: amount}();

        // Fund the attacker with enough to deposit
        vm.deal(attackerAddr, attackerDeposit);
        vm.prank(attackerAddr);
        c.deposit{value: attackerDeposit}();

        // Record credit before the attack
        uint256 creditBefore = c.credit(attackerAddr);

        // Attacker initiates withdrawAll, which will re-enter
        uint256 balanceBefore = address(c).balance;
        vm.prank(attackerAddr);
        attacker.attack();
        uint256 balanceAfter = address(c).balance;

        // Amount transferred to attacker = its balance after - (initial balance + attackerDeposit - creditBefore withdrawn?)
        // Simpler: total ETH received by attacker = attacker.balance after - attacker.balance before
        // Attacker's net gain = (attacker.balance after) - (initial funding - attackerDeposit deposited)
        // But we need a property directly readable from C.
        // Better: the total ETH sent out during the call (balanceBefore - balanceAfter) must NOT exceed creditBefore.
        // Because creditBefore is the legitimate maximum the attacker could withdraw based on the initial state.
        uint256 totalSent = balanceBefore - balanceAfter;
        assertTrue(totalSent <= creditBefore);
    }
}

contract Attacker {
    C public target;
    constructor(C _target) { target = _target; }
    function attack() external {
        target.withdrawAll();
    }
    receive() external payable {
        // Re-enter once if there is still credit (which the bug allows)
        // We stop after one re-entry to avoid infinite loop, but one re-entry is enough to break the invariant
        if (address(target).balance >= msg.value) {
            target.withdrawAll();
        }
    }
}

